BEGIN;
DO $$BEGIN
 IF to_regclass('public.bsc_gamagori_phase13_fixture_events') IS NULL OR to_regclass('public.bs_race_events') IS NOT NULL THEN RAISE EXCEPTION 'not_expected_phase13_isolation';END IF;
 IF (SELECT count(*) FROM public.bsc_gamagori_chart_ratings)<>6 THEN RAISE EXCEPTION 'isolation_snapshot_changed';END IF;
END$$;
